const PROCESSING_FEE: i64 = 5;

const FIRST_INSURANCE_SURCHARGE: f64 = 0.10;

const SWORD_BASE_PREMIUM: f64 = 100.0;
const AMULET_BASE_PREMIUM: f64 = 60.0;
const STAFF_BASE_PREMIUM: f64 = 80.0;
const POTION_BASE_PREMIUM: f64 = 40.0;

/// The MHPCO price list: the base premium each insurable item type carries.
fn base_premium(item: &Item) -> f64 {
    match item.item_type.as_str() {
        "amulet" => AMULET_BASE_PREMIUM,
        "staff" => STAFF_BASE_PREMIUM,
        "potion" => POTION_BASE_PREMIUM,
        _ => SWORD_BASE_PREMIUM,
    }
}

/// The policy base premium: the sum of the base premiums of all insured items.
fn policy_base_premium(items: &[Item]) -> f64 {
    items.iter().map(base_premium).sum()
}

/// Policy-wide modifiers, applied to the policy base premium.
fn apply_policy_modifiers(base: f64, _customer: &Customer, _previous_quotes: usize) -> f64 {
    base + base * FIRST_INSURANCE_SURCHARGE
}

/// Amounts are rounded in the MHPCO's favor: a premium is rounded up.
fn round_in_mhpco_favor(premium: f64) -> i64 {
    premium.ceil() as i64
}

pub fn quote(customer: &Customer, items: &[Item], previous_quotes: usize) -> i64 {
    let base = policy_base_premium(items);
    let premium = apply_policy_modifiers(base, customer, previous_quotes);
    round_in_mhpco_favor(premium) + PROCESSING_FEE
}

